// Domain A: Toggle
always_ff @(posedge clkA or negedge rstA_n) if (!rstA_n) t_q <= 1'b0; else if (pulse_in && !busy) t_q <= ~t_q;
// Domain B: 2-FF + XOR edge detect
always_ff @(posedge clkB or negedge rstB_n) if (!rstB_n) {s3, s2, s1} <= '0; else {s3, s2, s1} <= {s2, s1, t_q};
assign pulse_out = s2 ^ s3;
